    "Days a week": "الأيام في الأسبوع",
    "Weeks": "الأسابيع",
    "Weeks a year": "الأسابيع في السنة",
    "Overtime": "العمل الإضافي",
    "Hours of overtime a week": "ساعات العمل الإضافي في الأسبوع",
