    "A fraction, 22/7, a decimal, 0.125, one with a part in brackets that comes again, 0.1(6), or a calculation.": "كسر، 22/7، أو عدد عشري، 0.125، أو عدد بجزء متكرر بين قوسين، 0.1(6)، أو عملية حسابية.",
    "Value": "القيمة",
    "Continued fraction": "الكسر المستمر",
    "Of a calculation: as near as its digits tell.{v}": "لعملية حسابية: بأقرب ما تسمح به أرقامها.{v}",
    " Not a fraction of up to 10 digits.": " ليس كسرًا بحد أقصى 10 أرقام.",
    "As pies": "كفطائر",
    "Mixed": "عدد كسري",
    "A sum needs one size; a product A × B as many columns of A as rows of B.": "الجمع يتطلب حجمًا واحدًا؛ والضرب A × B يتطلب أن يساوي عدد أعمدة A عدد صفوف B.",
    "Time between dates": "المدة بين تاريخين",
    "The time from one date to another: in years, months and days; then the whole years, months and weeks of it, its days, its weekdays, Monday to Friday, both dates in, and its hours, each below 0 where the second date is before the first. An empty date is today.": "المدة من تاريخ إلى آخر: بالسنوات والأشهر والأيام؛ ثم كامل سنواتها وأشهرها وأسابيعها، وأيامها، وأيام العمل فيها من الاثنين إلى الجمعة شاملة التاريخين، وساعاتها، وكلها سالبة إن كان التاريخ الثاني قبل الأول. والتاريخ الفارغ هو اليوم.",
    "Add or subtract time": "إضافة مدة أو طرحها",
    "A date some years, months and days on, below 0 to go back: the date and its weekday, its day of the year and its week. The years and months go first; a month from 31 January is the last day of February. An empty date is today.": "التاريخ بعد عدد من السنوات والأشهر والأيام، والسالب للرجوع: التاريخ ويومه من الأسبوع، وترتيبه في السنة، ورقم أسبوعه. تُحسب السنوات والأشهر أولًا؛ فبعد شهر من 31 يناير يأتي آخر يوم في فبراير. والتاريخ الفارغ هو اليوم.",
    "Date": "التاريخ",
    "Time zones": "المناطق الزمنية",
    "A time in one place, and the same time in another: the time is now at first, to type over, and empty again is now. Summer time is as each place has it today.": "وقت في مكان، والوقت المقابل له في مكان آخر: يبدأ بالوقت الحالي لتكتب فوقه، ويعود إليه إذا أفرغته. والتوقيت الصيفي كما هو في كل مكان اليوم.",
    "Time": "الوقت",
    "Unix time": "وقت يونكس",
    "One way or the other. Unix → Date: the date and time of a Unix timestamp, the seconds from 1 January 1970 in UTC, or of 13 digits its milliseconds, in UTC, here, and in ISO 8601. Date → Unix: the timestamp of a date and time, in UTC or the time here; an empty date is today, an empty time midnight.": "في الاتجاهين. يونكس ← تاريخ: تاريخ ووقت طابع يونكس الزمني، أي الثواني منذ 1 يناير 1970 بتوقيت UTC، أو بالميلي ثانية إذا كان من 13 رقمًا، بتوقيت UTC والتوقيت المحلي وبصيغة ISO 8601. تاريخ ← يونكس: الطابع الزمني لتاريخ ووقت، بتوقيت UTC أو المحلي؛ والتاريخ الفارغ هو اليوم، والوقت الفارغ منتصف الليل.",
    "Convert": "التحويل",
