    "Seconds from 1 January 1970, in UTC.": "الثواني منذ 1 يناير 1970، بتوقيت UTC.",
    "The date and time in the time here.": "التاريخ والوقت بالتوقيت المحلي.",
    "The date and time in UTC.": "التاريخ والوقت بتوقيت UTC.",
