    "Bit {b}": "البت {b}",
    "Copy table": "نسخ الجدول",
    "Up to 10×10: from row {i}, column {j} this one of {cells}×{cells2} does not fit.": "حتى 10×10: من الصف {i} والعمود {j}، لا تتسع هذه المصفوفة {cells}×{cells2}.",
    " Click to close it.": " انقر لإغلاقه.",
    " Click to open it.": " انقر لفتحه.",
    "Data": "البيانات",
    "Summary": "الملخص",
    "Whether the mean of a sample differs from μ₀, by Student's t: of its numbers, or of its mean x̄, standard deviation s and size n. Its interval is where the mean is, with the chance of the level.": "هل يختلف متوسط عينة عن μ₀، باختبار t لستيودنت: من أعدادها، أو من متوسطها x̄ وانحرافها المعياري s وحجمها n. وفترتها هي المجال الذي يقع فيه المتوسط باحتمال المستوى.",
    "Two-sample t-test": "اختبار t لعينتين",
    "Whether the means of two samples differ, by Welch's t, or by t pooled where their spreads are taken as the same: of their numbers, or of the mean, standard deviation and size of each. Its interval is of the difference of the means.": "هل يختلف متوسطا عينتين، باختبار t لويلش، أو باختبار t المجمَّع حين يُفترض تساوي تشتتهما: من أعدادهما، أو من متوسط كل منهما وانحرافه المعياري وحجمه. وفترتها هي فترة الفرق بين المتوسطين.",
    "Sample 1": "العينة 1",
    "Sample 2": "العينة 2",
    "Spread": "التشتت",
    "Welch": "ويلش",
    "Pooled": "مجمَّع",
    "Paired t-test": "اختبار t للعينات المزدوجة",
    "Whether two measures of the same things differ, before and after: a pair on each line, as two columns of a spreadsheet; the t of their differences, the second less the first, against μd, 0 at first.": "هل يختلف قياسان للأشياء نفسها، قبل وبعد: زوج في كل سطر، كعمودين من جدول بيانات؛ واختبار t لفروقهما، الثاني ناقص الأول، مقابل μd، وهي 0 في البداية.",
    "Pairs": "الأزواج",
    "Whether the mean of a sample differs from μ₀, where the standard deviation σ of all is known: of its numbers, or of its mean x̄ and size n.": "هل يختلف متوسط عينة عن μ₀، حين يكون الانحراف المعياري σ للمجتمع معلومًا: من أعدادها، أو من متوسطها x̄ وحجمها n.",
    "Proportion z-test": "اختبار z لنسبة",
    "Whether a proportion, x of n, differs from the chance p₀, by the normal distribution. Its interval is of the proportion.": "هل تختلف نسبة، x من n، عن الاحتمال p₀، بالتوزيع الطبيعي. وفترتها هي فترة النسبة.",
    "Two-proportion z-test": "اختبار z لنسبتين",
    "Whether two proportions, x₁ of n₁ and x₂ of n₂, differ, by their pooled proportion. Its interval is of their difference.": "هل تختلف نسبتان، x₁ من n₁ وx₂ من n₂، باستخدام نسبتهما المجمَّعة. وفترتها هي فترة الفرق بينهما.",
    "χ² goodness of fit": "اختبار χ² لحسن المطابقة",
    "Whether counts fit what was expected: the counts of each kind, and what was expected of each, as counts or as a ratio, 9:3:3:1 as Mendel's peas; none expected is each the same.": "هل تطابق التكرارات ما كان متوقعًا: تكرار كل فئة، والمتوقع لكل منها كتكرارات أو كنسبة، 9:3:3:1 كبازلاء مندل؛ وإن لم يُحدَّد المتوقع فهو متساوٍ للجميع.",
    "Observed": "المشاهَد",
    "Expected": "المتوقَّع",
    "χ² test of independence": "اختبار χ² للاستقلال",
    "Whether the rows and the columns of a table of counts are independent: a row on each line, as a block of a spreadsheet is pasted. Each count expected is its row's times its column's, over all.": "هل صفوف جدول تكرارات وأعمدته مستقلة: صف في كل سطر، كما تُلصق كتلة من جدول بيانات. والتكرار المتوقع لكل خلية هو مجموع صفها في مجموع عمودها مقسومًا على المجموع الكلي.",
    "ANOVA": "ANOVA",
    "One-way analysis of variance: whether the means of three groups or more, or two, differ. A group on each line, its numbers apart by spaces.": "تحليل التباين الأحادي: هل تختلف متوسطات ثلاث مجموعات أو أكثر، أو مجموعتين. مجموعة في كل سطر، تفصل بين أعدادها مسافات.",
    "Groups": "المجموعات",
    "Correlation test": "اختبار الارتباط",
    "Whether pairs are correlated, by the t of the slope of their line, as LinRegTTest: x and y on each line. With Spearman's ρ, of their ranks, for pairs that go up or down together but not in a line.": "هل الأزواج مترابطة، باختبار t لميل خطها، كما في LinRegTTest: x وy في كل سطر. مع ρ لسبيرمان من رتبها، للأزواج التي تزداد أو تنقص معًا دون أن تكون على خط مستقيم.",
    "Reject H<sub>0</sub>": "رفض H<sub>0</sub>",
    "Do not reject H<sub>0</sub>": "عدم رفض H<sub>0</sub>",
    "{level}% interval from": "فترة {level}% من",
    "α is a chance between 0 and 1, as 0.05.": "α احتمال بين 0 و1، مثل 0.05.",
    "The level is a chance between 0 and 1, as 0.95.": "المستوى احتمال بين 0 و1، مثل 0.95.",
    "Left out: {left}{v}. ": "أُهمل: {left}{v}. ",
    "p < α: significant at {alpha}.": "p < α: دالّ إحصائيًا عند {alpha}.",
    "p ≥ α: not significant at {alpha}.": "p ≥ α: غير دالّ إحصائيًا عند {alpha}.",
    "SE": "SE",
    "Pooled p̂": "p̂ المجمَّعة",
    "Each kind": "كل فئة",
    "As many expected as observed: {values}.": "عدد القيم المتوقعة بعدد المشاهَدة: {values}.",
    "{n} kinds expect fewer than 5: χ² is rough.": { few: "{n} فئات يُتوقع لها أقل من 5: χ² تقريبي.", many: "{n} فئة يُتوقع لها أقل من 5: χ² تقريبي.", one: "فئة واحدة يُتوقع لها أقل من 5: χ² تقريبي.", two: "فئتان يُتوقع لهما أقل من 5: χ² تقريبي.", zero: "لا فئة يُتوقع لها أقل من 5.", other: "{n} فئة يُتوقع لها أقل من 5: χ² تقريبي." }, // one: "{n} kind expects fewer than 5: χ² is rough."
    "Cramér's V": "V لكرامر",
    "{n} counts expected are below 5: χ² is rough.": { few: "{n} أعداد متوقعة أقل من 5: χ² تقريبي.", many: "{n} عددًا متوقعًا أقل من 5: χ² تقريبي.", one: "عدد متوقع واحد أقل من 5: χ² تقريبي.", two: "عددان متوقعان أقل من 5: χ² تقريبي.", zero: "لا عدد متوقع أقل من 5.", other: "{n} عدد متوقع أقل من 5: χ² تقريبي." }, // one: "{n} count expected is below 5: χ² is rough."
    "df between": "df بين المجموعات",
