    "Binding and Hill": "الارتباط ومعادلة هيل",
    "How much of a protein has its ligand bound at [L], by Hill's equation, of K, the [L] half bound, and n, its cooperativity: 1 none, as myoglobin, above 1 as haemoglobin, some 2.8, K 26 mmHg of O₂. The [L] for 10%, 50% and 90%, and the curve drawn, beside that of n = 1.": "نسبة البروتين المرتبط بربيطته عند [L] وفق معادلة هيل، من K وهو [L] عند ارتباط النصف، وn التعاونية: 1 دون تعاون كالميوغلوبين، وأكثر من 1 كالهيموغلوبين، نحو 2.8، وK = 26 mmHg من O₂. مع [L] عند 10% و50% و90%، ورسم المنحنى بجانب منحنى n = 1.",
    "Dose–response, IC<sub>50</sub>": "الجرعة والاستجابة، IC<sub>50</sub>",
    "A dose and its response fitted by the four-parameter logistic, Prism's variable slope: a concentration and its response on each line, repeats too. The bottom, the top, the IC₅₀ of a response that falls or the EC₅₀ of one that rises, the Hill slope, R², and the concentrations of 10% and 90% of the effect; or the ends held at 0 and 100, of responses in %. The curve drawn on a scale of logarithms.": "جرعة واستجابتها، ملاءمةً بالمنحنى اللوجستي رباعي المعاملات، أي الميل المتغير في Prism: تركيز واستجابته في كل سطر، والتكرارات أيضًا. مع القاع والقمة، وIC₅₀ لاستجابة تنخفض أو EC₅₀ لاستجابة ترتفع، وميل هيل، وR²، وتركيزا 10% و90% من التأثير؛ أو مع تثبيت الطرفين عند 0 و100 لاستجابات بالنسبة المئوية. ويُرسم المنحنى بمقياس لوغاريتمي.",
