    "A solution's osmolarity, of a solute's molarity and the particles each makes, and whether it is hypotonic, isotonic or hypertonic to a cell, some 300 mOsm/L, as blood's: which way water goes, and a red blood cell in it, drawn.": "أسمولية محلول من مولارية مذاب وعدد الجسيمات التي يكوّنها كل جزيء، وهل هو ناقص التوتر أو متساويه أو مفرطه بالنسبة لخلية، نحو 300 mOsm/L كالدم: اتجاه حركة الماء، وخلية دم حمراء فيه، مع الرسم.",
    "Solute": "المذاب",
    "C, mM": "C, mM",
    "Cell, mOsm/L": "الخلية، mOsm/L",
    "Surface area to volume": "نسبة المساحة إلى الحجم",
    "A cube, a sphere or a cylinder, as a cell: its surface, its volume and their ratio, the reason cells stay small; the shape drawn, and its SA:V as it grows.": "مكعب أو كرة أو أسطوانة كخلية: مساحة سطحها وحجمها والنسبة بينهما، وهو سبب بقاء الخلايا صغيرة؛ مع رسم الشكل ونسبة SA:V مع نموه.",
    "Cube": "مكعب",
    "How much faster a rate goes 10 °C warmer: of two rates and their temperatures, Q₁₀, some 2 to 3 of a reaction of enzymes; or of Q₁₀, the rate at another temperature. Drawn.": "كم تتسارع عملية عند ارتفاع الحرارة 10 °C: من معدلين ودرجتي حرارتهما، Q₁₀، نحو 2 إلى 3 لتفاعل إنزيمي؛ أو من Q₁₀، المعدل عند درجة حرارة أخرى. مع الرسم.",
    "Two rates": "معدلان",
    "Diffusion": "الانتشار",
    "Fick's law: the rate a substance crosses a membrane or a layer, of its diffusion coefficient D, in m²/s, O₂ in water 2e-9, glucose 6.7e-10, the area A, m², the difference of concentration ΔC, mol/m³, and the thickness d, m; drawn. Or how long it takes to spread a distance x, the reason diffusion serves only small distances, drawn.": "قانون فيك: معدل عبور مادة لغشاء أو طبقة، من معامل انتشارها D بوحدة m²/s، ‏O₂ في الماء 2e-9 والغلوكوز 6.7e-10، والمساحة A بوحدة m²، وفرق التركيز ΔC بوحدة mol/m³، والسمك d بوحدة m؛ مع الرسم. أو الزمن اللازم للانتشار مسافة x، وهو سبب أن الانتشار لا يصلح إلا للمسافات الصغيرة، مع الرسم.",
    "A rate": "معدل",
    "A time": "زمن",
