    "Membrane potential": "جهد الغشاء",
    "The equilibrium potential of an ion by Nernst, of its concentrations outside and in, mM; or the resting potential by Goldman, Hodgkin and Katz, of the permeabilities and concentrations of K⁺, Na⁺ and Cl⁻. At 37 °C unless typed. Each drawn on a scale of mV.": "جهد الاتزان لأيون وفق نيرنست، من تركيزيه في الخارج والداخل بالـ mM؛ أو جهد الراحة وفق غولدمان-هودجكين-كاتز، من نفاذيات K⁺ وNa⁺ وCl⁻ وتراكيزها. عند 37 °C ما لم يُكتب غيرها. ويُرسم كل منها على مقياس بالـ mV.",
