    "Whether a reaction goes on its own: of its ΔG°′, kJ/mol, and Q, its products over its reactants, the ΔG, below 0 going forward; and its K at equilibrium. ATP to ADP is −30.5. Drawn against Q.": "هل يحدث تفاعل تلقائيًا: من ΔG°′ بوحدة kJ/mol، وQ نسبة النواتج إلى المتفاعلات، قيمة ΔG، والسالبة تعني سيره إلى الأمام؛ وثابت اتزانه K. تحويل ATP إلى ADP قيمته −30.5. مع الرسم مقابل Q.",
    "ΔG°′, kJ/mol": "ΔG°′، kJ/mol",
    "Heart and blood pressure": "القلب وضغط الدم",
    "Of the heart rate and stroke volume, the cardiac output; of the blood pressures, systolic over diastolic, the mean arterial pressure and the pulse pressure; and of both, the resistance of the vessels. The pressure drawn, beat by beat.": "من معدل نبض القلب وحجم الضربة، النتاج القلبي؛ ومن ضغطي الدم الانقباضي والانبساطي، متوسط الضغط الشرياني وضغط النبض؛ ومن كليهما، مقاومة الأوعية. مع رسم الضغط ضربةً بضربة.",
