    "Respiration": "التنفس",
    "Of glucose, in g, what aerobic respiration takes and makes: the O₂, CO₂ and water, and some 30 to 32 ATP each, drawn by where it is made. Or the respiratory quotient, of the CO₂ made and the O₂ taken, and what it burns, 1 of carbohydrate, 0.8 of protein and 0.7 of fat, drawn.": "ما يستهلكه التنفس الهوائي وينتجه من غرامات الغلوكوز: الأكسجين وثاني أكسيد الكربون والماء، ونحو 30 إلى 32 جزيء ATP لكل جزيء، مرسومة حسب مكان إنتاجها. أو حاصل التنفس من CO₂ الناتج وO₂ المستهلك، وما يُحرق: 1 للكربوهيدرات، و0.8 للبروتين، و0.7 للدهون، مع الرسم.",
