    "Diagnostic tests": "الاختبارات التشخيصية",
    "How good a test is: of its true and false positives and negatives, or of its sensitivity, its specificity and how common the illness is. Its sensitivity, specificity, predictive values, likelihood ratios and accuracy, with 95% intervals of counts; a thousand people drawn by what the test says of them.": "مدى جودة اختبار: من نتائجه الإيجابية والسلبية الصادقة والكاذبة، أو من حساسيته ونوعيته وشيوع المرض. مع الحساسية والنوعية والقيم التنبؤية ونسب الأرجحية والدقة، وفترات ثقة 95% للأعداد؛ ورسم ألف شخص حسب نتيجة الاختبار لكل منهم.",
