    "A study's 2 × 2 table, those exposed or treated and those not, with the outcome and without: the risk of each, the relative risk and the odds ratio with their 95% intervals, the difference of the risks, and the number needed to treat, or to harm. Drawn.": "جدول 2 × 2 لدراسة، المعرَّضون أو المعالَجون وغيرهم، مع النتيجة ودونها: خطر كل فئة، والخطر النسبي ونسبة الأرجحية مع فترتي ثقة 95%، وفرق الخطرين، والعدد اللازم علاجه، أو اللازم لحدوث ضرر. مع الرسم.",
    "Exposed, with it": "معرَّض، مصاب",
