    "Not, without": "غير معرَّض، غير مصاب",
    "Epidemic, SIR": "الوباء، نموذج SIR",
    "An epidemic of those who can catch it, S, the infectious, I, and the recovered, R: of the people, those ill at first, R₀, the days ill and a part vaccinated, its peak, when, and how many catch it in all; and the part to vaccinate for herd immunity. Drawn day by day.": "وباء بين القابلين للعدوى S والمعدين I والمتعافين R: من عدد السكان، والمرضى في البداية، وR₀، وأيام المرض، ونسبة الملقحين: ذروته وموعدها، وعدد من يصابون إجمالًا؛ ونسبة التلقيح اللازمة لمناعة القطيع. مع الرسم يومًا بيوم.",
    "Ill at first": "المرضى في البداية",
