    "Vaccinated": "الملقحون",
    "Oxygen and haemoglobin": "الأكسجين والهيموغلوبين",
    "How much of haemoglobin carries O₂ at a PO₂, by Severinghaus's curve, moved by the Bohr effect: a lower pH, more CO₂ or warmer to the right, giving O₂ up; fetal haemoglobin to the left, and myoglobin a hyperbola, far to the left. Its P₅₀, the saturation, what it gives up from the lungs, 100 mmHg, to the tissues, 40, and with Hb the O₂ in the blood. Drawn beside the usual curve.": "نسبة الهيموغلوبين المحمَّل بالأكسجين عند PO₂ معين، وفق منحنى سيفيرنغهاوس، مزاحًا بتأثير بور: انخفاض pH أو زيادة CO₂ أو ارتفاع الحرارة يزيحه إلى اليمين فيطلق الأكسجين؛ وهيموغلوبين الجنين إلى اليسار، والميوغلوبين قطع زائد بعيد إلى اليسار. مع P₅₀ والتشبع وما يطلقه بين الرئتين عند 100 mmHg والأنسجة عند 40، ومع Hb محتوى الدم من O₂. مرسوم بجانب المنحنى المعتاد.",
    "Adult Hb": "هيموغلوبين البالغ",
