    "Hb": "Hb",
    "Action potential": "جهد الفعل",
    "Hodgkin and Huxley's squid axon: a current, µA/cm², for so long; whether it fires, its peak and how many times, at a temperature, 6.3 °C as theirs. Its voltage drawn, and its gates, m opening Na⁺'s channels and h closing them, n opening K⁺'s.": "محور الحبار عند هودجكين وهكسلي: تيار بوحدة µA/cm² لمدة معينة؛ هل يطلق جهد فعل، وذروته وعدد مرات إطلاقه، عند درجة حرارة معينة، 6.3 °C كما في تجربتهما. مع رسم جهده وبواباته: m تفتح قنوات Na⁺ وh تغلقها، وn تفتح قنوات K⁺.",
    "Current, µA/cm²": "التيار، µA/cm²",
