    "Kidneys": "الكليتان",
    "The filtration of the kidneys: eGFR by CKD-EPI of 2021, without race, of creatinine, age and sex, and its stage; with the weight, Cockcroft and Gault's creatinine clearance, used for doses. Or a clearance, of the urine's concentration, its flow and the plasma's; or the plasma's osmolality. For learning, not to diagnose.": "ترشيح الكليتين: معدل الترشيح الكبيبي المقدَّر eGFR وفق CKD-EPI لعام 2021 دون العرق، من الكرياتينين والعمر والجنس، ومرحلته؛ ومع الوزن، تصفية الكرياتينين وفق كوكروفت-غولت المستخدمة لحساب الجرعات. أو تصفية مادة من تركيزها في البول وتدفقه وتركيزها في البلازما؛ أو أسمولالية البلازما. للتعلم لا للتشخيص.",
