    "BMI and energy": "مؤشر كتلة الجسم والطاقة",
    "Of the height, weight, age and sex of an adult: the body mass index and its class, drawn, the weights of a BMI of 18.5 to 25 at the height, the body's surface by Mosteller, the basal metabolic rate by Mifflin and St Jeor, and the energy a day at an activity.": "من طول بالغ ووزنه وعمره وجنسه: مؤشر كتلة الجسم وفئته مع الرسم، والأوزان المقابلة لمؤشر بين 18.5 و25 عند هذا الطول، ومساحة سطح الجسم وفق موستيلر، ومعدل الأيض الأساسي وفق ميفلين-سانت جيور، والطاقة اليومية حسب مستوى النشاط.",
