    "Drug levels": "مستويات الدواء",
    "A drug given every so many hours, by IV bolus or by mouth: of the dose, its volume of distribution, its half-life and, by mouth, the part absorbed and how fast, k<sub>a</sub>: its level over the doses, drawn, its peak and trough once steady, the clearance, the time to steady, some 4 to 5 half-lives, and a loading dose to reach it at once. For learning, not to dose.": "دواء يُعطى كل عدد من الساعات، بحقنة وريدية أو بالفم: من الجرعة وحجم التوزيع وعمر النصف، وبالفم نسبة الامتصاص وسرعته k<sub>a</sub>: مستواه عبر الجرعات مرسومًا، وذروته وقاعه بعد الاستقرار، والتصفية، وزمن الوصول إلى الاستقرار، نحو 4 إلى 5 أعمار نصف، وجرعة تحميل لبلوغه فورًا. للتعلم لا لتحديد الجرعات.",
