    "Population growth": "النمو السكاني",
    "A population growing exponentially, at the rate r, or logistically, slowing to its carrying capacity K: its size at t, how fast it grows then, the doubling time, and of the logistic, when it grows fastest, at K/2. Its curve drawn.": "مجتمع ينمو نموًا أسيًا بمعدل r، أو لوجستيًا يتباطأ حتى قدرة الاستيعاب K: حجمه عند t، وسرعة نموه حينها، وزمن التضاعف، وفي النمو اللوجستي موعد أسرع نمو، عند K/2. مع رسم منحناه.",
    "Logistic": "لوجستي",
    "Predator and prey": "المفترس والفريسة",
    "Lotka and Volterra: prey N, which grow at a and are eaten at b, and predators P, which die at c and grow at d of what they eat: their cycles drawn over a time, and drawn against each other, round their balance, N = c/d and P = a/b.": "نموذج لوتكا-فولتيرا: الفرائس N تنمو بمعدل a وتُؤكل بمعدل b، والمفترسات P تموت بمعدل c وتنمو بمعدل d مما تأكله: دوراتها مرسومة عبر الزمن، ومرسومة إحداها مقابل الأخرى حول نقطة اتزانها، N = c/d وP = a/b.",
    "Prey": "الفرائس",
    "Predators": "المفترسات",
    "Mark and recapture": "الوسم وإعادة الاصطياد",
    "The size of a population by Lincoln and Petersen: M marked and let go, then C caught, R of them marked; and by Chapman, less biased of a few, with its 95% interval. The second catch drawn.": "حجم مجتمع وفق لينكولن-بيترسن: يُوسم M ويُطلق، ثم يُصطاد C منها R موسومة؛ ووفق تشابمان الأقل تحيزًا مع الأعداد الصغيرة، مع فترة ثقة 95%. مع رسم الاصطياد الثاني.",
    "Marked, M": "الموسومة، M",
    "Caught, C": "المصطادة، C",
    "Recaptured, R": "المعاد اصطيادها، R",
    "Diversity indices": "مؤشرات التنوع",
    "The diversity of a community, of the count of each species: the richness, Simpson's index, its 1 – D and 1/D, Shannon's H and its evenness; the species drawn, the commonest first.": "تنوع مجتمع أحيائي من عدد أفراد كل نوع: الغنى النوعي، ومؤشر سيمبسون و1 – D و1/D، ومؤشر شانون H وتكافؤه؛ مع رسم الأنواع، الأكثر شيوعًا أولًا.",
    "Life table": "جدول الحياة",
    "How many of a cohort are alive at the start of each age: the part surviving, those dying, the chance of dying in each and how long each has left to live; the survivorship curve drawn on a scale of logarithms, as type I, II or III.": "عدد الأحياء من فوج في بداية كل عمر: نسبة الباقين، والموتى، واحتمال الموت في كل عمر، والعمر المتوقع المتبقي؛ مع رسم منحنى البقاء بمقياس لوغاريتمي، من النمط I أو II أو III.",
    "Alive, nₓ": "الأحياء، nₓ",
    "Alive": "الأحياء",
    "Energy pyramid": "هرم الطاقة",
    "The energy at each trophic level, from the producers up, so much passing on each step, some 10%. Drawn.": "الطاقة في كل مستوى غذائي بدءًا من المنتجين، وينتقل منها قدر معين في كل خطوة، نحو 10%. مع الرسم.",
    "Producers": "المنتجون",
