    "Primary productivity": "الإنتاجية الأولية",
    "By light and dark bottles: the dissolved oxygen at first, in the light and in the dark, mg/L, after so many hours: the net and gross primary productivity and the respiration, as O₂ and as carbon, drawn.": "بطريقة القارورتين المضيئة والمعتمة: الأكسجين المذاب في البداية، وفي الضوء وفي الظلام بالـ mg/L بعد عدد من الساعات: الإنتاجية الأولية الصافية والإجمالية والتنفس، كأكسجين وككربون، مع الرسم.",
    "At first": "في البداية",
    "Dark": "المعتمة",
    "Natural selection": "الانتخاب الطبيعي",
    "A gene under selection, mating at random: p of A at first and the fitness of AA, Aa and aa: p and q after so many generations, drawn, and the mean fitness.": "جين تحت الانتخاب في تزاوج عشوائي: تكرار A الأولي p، وصلاحية AA وAa وaa: قيمتا p وq بعد عدد من الأجيال مرسومتين، ومتوسط الصلاحية.",
    "Generations": "الأجيال",
