    "w<sub>Aa</sub>": "w<sub>Aa</sub>",
    "wAa": "wAa",
    "Genetic drift": "الانجراف الوراثي",
    "Chance alone: populations of N each, p of an allele at first, drawn generation by generation as Wright and Fisher have it, how many fix or lose it, and the heterozygosity left. Again for another run.": "الصدفة وحدها: مجتمعات حجم كل منها N، وتكرار أليل أولي p، مرسومة جيلًا بجيل وفق نموذج رايت-فيشر: كم منها يثبت فيه الأليل أو يفقده، والتغاير الزيجوتي المتبقي. اضغط «مرة أخرى» لتجربة جديدة.",
    "Populations": "المجتمعات",
    "Leslie matrix": "مصفوفة ليزلي",
    "A population by its ages: the births to each of each age, the part of each surviving to the next, and the numbers of each at first: λ, how much it grows each step, the ages it settles to, R₀, each one's offspring in its life, and its numbers step by step, drawn by age.": "مجتمع حسب أعماره: المواليد لكل فرد من كل عمر، ونسبة من يبقى من كل عمر إلى التالي، وعدد كل عمر في البداية: λ مقدار النمو في كل خطوة، والتوزيع العمري الذي يستقر عليه، وR₀ نسل كل فرد طوال حياته، وأعداده خطوةً بخطوة مرسومة حسب العمر.",
    "Births, of each age": "المواليد لكل عمر",
    "Births": "المواليد",
    "Surviving to the next": "الباقون إلى التالي",
    "Surviving": "الباقون",
    "Competition": "التنافس",
    "Two species competing for the same, by Lotka and Volterra: each one's numbers, r and K, and how much each takes of the other's room, α: which wins, or whether both live on, and at what; their numbers over time, drawn, and against each other, with each one's isocline, where it stops growing.": "نوعان يتنافسان على المورد نفسه، وفق لوتكا-فولتيرا: أعداد كل منهما وr وK، ومقدار ما يأخذه كل منهما من حيز الآخر α: أيهما يفوز، أو هل يتعايشان وعند أي أعداد؛ مع رسم أعدادهما عبر الزمن، وإحداهما مقابل الأخرى مع خط التساوي لكل منهما حيث يتوقف نموه.",
    "Species, area and rarefaction": "الأنواع والمساحة والتخلخل",
    "Of areas and the species in each, a pair on each line: the species–area curve, S = cA<sup>z</sup>, fitted, its z and c, and the species of another area. Or of the count of each species in a sample: the species expected in a smaller sample, by rarefaction, drawn, and by Chao1 the species there likely are, those not seen too.": "من مساحات وعدد الأنواع في كل منها، زوج في كل سطر: منحنى الأنواع-المساحة S = cA<sup>z</sup> ملاءمةً، وقيمتا z وc، وعدد الأنواع لمساحة أخرى. أو من عدد أفراد كل نوع في عينة: الأنواع المتوقعة في عينة أصغر بطريقة التخلخل مع الرسم، والأنواع المرجح وجودها وفق Chao1، بما فيها غير المرصودة.",
    "Areas": "المساحات",
    "Sample of": "عينة من",
    "Distance tree": "شجرة المسافات",
    "A tree of how alike taxa are: of a matrix of distances, a taxon to a line, its name and its distances; or of aligned sequences, a name and its sequence on each line, all of one length, by their Jukes–Cantor distances; by UPGMA, as of a steady molecular clock, or by neighbour joining. The tree drawn, and in Newick to copy.": "شجرة تُظهر مدى تشابه الأصنوفات: من مصفوفة مسافات، أصنوفة في كل سطر باسمها ومسافاتها؛ أو من تسلسلات محاذاة، اسم وتسلسله في كل سطر، كلها بالطول نفسه، بمسافات جوكس-كانتور؛ بطريقة UPGMA كما في ساعة جزيئية ثابتة، أو بطريقة ضم الجيران. مع رسم الشجرة وصيغة Newick للنسخ.",
    "Distances": "المسافات",
    "Sequences": "التسلسلات",
    "UPGMA": "UPGMA",
    "Neighbour joining": "ضم الجيران",
    "Taxa": "الأصنوفات",
    "Molecular clock": "الساعة الجزيئية",
    "How long ago two lineages split: of the part of the sites that differ, p, or of two aligned sequences, the substitutions a site by Jukes and Cantor, sites changing more than once, and by Kimura, of transitions and transversions; with a rate of substitutions a site a year, some 10⁻⁹ of mammals' DNA, the time since they split; or of that time, the rate. p and d drawn.": "متى افترقت سلالتان: من نسبة المواقع المختلفة p، أو من تسلسلين محاذاة، الاستبدالات لكل موقع وفق جوكس-كانتور مع احتساب تغير الموقع أكثر من مرة، ووفق كيمورا من الانتقالات والتحولات؛ ومع معدل استبدال لكل موقع في السنة، نحو 10⁻⁹ لـ DNA الثدييات، الزمن منذ الافتراق؛ أو من ذلك الزمن، المعدل. مع رسم p وd.",
    "Two sequences": "تسلسلان",
    "Rate, /site/year": "المعدل، /موقع/سنة",
    "Rate": "المعدل",
    "Or the time, years": "أو الزمن، سنوات",
