    "One degree of freedom: three classes, less one, less p worked out of them.": "درجة حرية واحدة: ثلاث فئات، ناقص واحد، ناقص p المحسوبة منها.",
    "{bad} is not a count.": "{bad} ليس عددًا صحيحًا للعدّ.",
