    "α is between 0 and 1, as 0.05.": "α بين 0 و1، مثل 0.05.",
    "Counts of 0 or more, some above 0, and each part of the ratio above 0.": "أعداد صفر أو أكثر، بعضها أكبر من 0، وكل جزء من النسبة أكبر من 0.",
    "Where χ² falls": "موقع χ²",
