    "Parental": "أبوية",
    "Double crossovers": "العبور المزدوج",
    "The outer distance is the sum of the two: counted straight from the classes it is {v} cM, the double crossovers missed.": "المسافة الخارجية مجموع المسافتين: وبالعدّ المباشر من الفئات تساوي {v} cM، لأن العبور المزدوج لا يُحتسب.",
    "Four counts of 0 or more.": "أربعة أعداد، صفر أو أكثر.",
    "Some offspring.": "بعض النسل.",
    "Half or more recombined: not linked, or so far apart they assort independently.": "نصفه أو أكثر معاد الاتحاد: غير مرتبطين، أو متباعدان حتى يتوزعا مستقلين.",
    "Haldane and Kosambi count the crossovers a large distance hides.": "دالتا هالدين وكوسامبي تحتسبان حالات العبور التي تخفيها المسافات الكبيرة.",
    "p from 0 to 1, n a whole number from 1 to 1000, and k from 0 to n.": "p من 0 إلى 1، وn عدد صحيح من 1 إلى 1000، وk من 0 إلى n.",
    "Each count": "كل عدد",
    "With k, how many of them have it.": "ومع k، عدد من يحملونها.",
    "h² from 0 to 1, of V_A no more than V_P, above 0, and both means.": "h² من 0 إلى 1، أو V_A لا تزيد على V_P الموجبة، والمتوسطان.",
    "The population red, its offspring blue, and the parents' mean": "المجتمع بالأحمر، ونسله بالأزرق، ومتوسط الآباء",
    "R = h²S: of what the parents differ by, only the part handed down by genes, h², shows in their offspring.": "R = h²S: من الفرق الذي يميز الآباء، لا يظهر في نسلهم إلا الجزء الموروث جينيًا، h².",
    "Its GC content along it, a window of {w} bases": "نسبة GC على امتداده، بنافذة من {w} قاعدة",
    "Not a base: {bad}. A, C, G, T or U, and the codes of IUPAC, as N.": "ليست قاعدة: {bad}. ‏A أو C أو G أو T أو U، ورموز IUPAC مثل N.",
