    "Livak's 2^−ΔΔCt takes both genes as doubling each cycle: with their efficiencies, Pfaffl's too.": "طريقة ليفاك 2^−ΔΔCt تفترض أن الجينين يتضاعفان في كل دورة: ومع كفاءتيهما، طريقة بفافل أيضًا.",
