    "The second catch": "الاصطياد الثاني",
    "Fewer than 7 recaptured: rough, and it may be biased.": "أقل من 7 معاد اصطيادها: تقديري، وقد يكون متحيزًا.",
    "It takes a closed population, the marks kept, and every animal as likely caught.": "يفترض مجتمعًا مغلقًا، والعلامات باقية، وتساوي احتمال اصطياد كل حيوان.",
