    "D, the chance two taken at random are of one species: the lower, the more diverse; H the higher.": "D احتمال أن يكون فردان مأخوذان عشوائيًا من النوع نفسه: كلما قلّ زاد التنوع؛ وH كلما زاد.",
    "Two ages or more.": "عمران أو أكثر.",
