    "mg O₂/L; GPP = NPP + respiration.": "mg O₂/L؛ والإنتاجية الإجمالية = الصافية + التنفس.",
    "p from 0 to 1, 1 to 10000 generations, fitnesses of 0 or more.": "p من 0 إلى 1، ومن 1 إلى 10000 جيل، وصلاحيات صفر أو أكثر.",
