    "N 1 to 10000, p from 0 to 1, 1 to 1000 generations and 1 to 20 populations, each whole.": "N من 1 إلى 10000، وp من 0 إلى 1، ومن 1 إلى 1000 جيل، ومن 1 إلى 20 مجتمعًا، وكلها أعداد صحيحة.",
