    "As in": "كما في",
    "As many counts as its ratio has parts, {e}.{v}": "عدد الأعداد بعدد أجزاء نسبتها، {e}.{v}",
    " Of {values}, {epistasis}, {epistasis2}, fits best.": " ومن {values}، الأنسب {epistasis}، {epistasis2}.",
    "They fit {e}: what differs may be chance": "تطابق {e}: والفروق قد تكون صدفة",
    "Fits best": "الأنسب",
    "A chance from 0 to 1, and 0 to 20 sons, whole.": "احتمال من 0 إلى 1، ومن 0 إلى 20 ابنًا، أعداد صحيحة.",
    "The family": "العائلة",
    "Her sons free of it, if she has any, lower the chance she carries it.": "أبناؤها غير المصابين، إن وُجدوا، يخفضون احتمال كونها حاملة.",
    "Each son free of it makes it less likely she carries it: by Bayes, {prior} × ½^{sons} over that and the {v} she does not.": "كل ابن غير مصاب يقلل احتمال كونها حاملة: وفق بايز، {prior} × ½^{sons} مقسومًا على ذلك مضافًا إليه {v} أنها غير حاملة.",
    "A penetrance from 0 to 100%.": "نفاذية من 0 إلى 100%.",
    "Fully penetrant: free of it, she does not carry it.": "نفاذية تامة: إن لم تظهر عليها فهي غير حاملة.",
