    "Red cells each can take": "خلايا الدم الحمراء التي يمكن لكل فصيلة تلقيها",
    "A and B codominant, both shown in AB, and O recessive to them; Rh⁺, of D, dominant.": "A وB متساويا السيادة ويظهران معًا في AB، وO متنحية أمامهما؛ وRh⁺ من D سائدة.",
