    "Solute, g/mol": "المذاب، g/mol",
    "i = {i}: {f} gives {i} ions, ideally; the real i is a little less.": "i = {i}: ‏{f} تعطي {i} أيونات نظريًا؛ وi الفعلية أقل قليلًا.",
    "{v}Kf {sv}, Kb {sv2} °C·kg/mol.": "{v}Kf {sv}، وKb {sv2} °C·kg/mol.",
    "Solubility in water at 25 °C": "الذائبية في الماء عند 25 °C",
    "Pick a salt in the table, its cation down the side, its anion across the top, or type it.": "اختر ملحًا من الجدول، كاتيونه على الجانب وأنيونه في الأعلى، أو اكتبه.",
    "Not in the table: a salt of Li⁺, Na⁺, K⁺, NH₄⁺, Mg²⁺, Ca²⁺, Sr²⁺, Ba²⁺, Al³⁺, Cr³⁺, Mn²⁺, Fe²⁺, Fe³⁺, Co²⁺, Ni²⁺, Cu²⁺, Zn²⁺, Ag⁺, Hg²⁺ or Pb²⁺ with nitrate, acetate, Cl⁻, Br⁻, I⁻, sulfate, carbonate, phosphate, hydroxide or sulfide.": "ليس في الجدول: ملح من Li⁺ أو Na⁺ أو K⁺ أو NH₄⁺ أو Mg²⁺ أو Ca²⁺ أو Sr²⁺ أو Ba²⁺ أو Al³⁺ أو Cr³⁺ أو Mn²⁺ أو Fe²⁺ أو Fe³⁺ أو Co²⁺ أو Ni²⁺ أو Cu²⁺ أو Zn²⁺ أو Ag⁺ أو Hg²⁺ أو Pb²⁺ مع النترات أو الأسيتات أو Cl⁻ أو Br⁻ أو I⁻ أو الكبريتات أو الكربونات أو الفوسفات أو الهيدروكسيد أو الكبريتيد.",
