    "The electrons it gained or lost are left out of its mass, as tables of molar mass do.": "الإلكترونات المكتسبة أو المفقودة مهملة في كتلته، كما في جداول الكتل المولية.",
    "Type a formula for its name, Fe2(SO4)3, or a name for its formula, iron(III) sulfate.": "اكتب صيغة لاسمها، Fe2(SO4)3، أو اسمًا لصيغته، iron(III) sulfate.",
    "{name} has more than one charge: write it in Roman numerals, {ox}.": "لـ {name} أكثر من شحنة: اكتبها بالأرقام الرومانية، {ox}.",
