    "VI": "VI",
    "VII": "VII",
    "VIII": "VIII",
    "Not one it names: salts, acids, ions, two nonmetals, the elements and some common compounds are.": "ليس مما يُسمّى: الأملاح والأحماض والأيونات ومركبات لافلزين والعناصر وبعض المركبات الشائعة.",
    "As a compound, hydrogen and the anion; in water -ide becomes hydro-…-ic acid.": "كمركب: الهيدروجين والأنيون؛ وفي الماء تصبح ‎-ide حمض hydro-…-ic.",
    "In water, -ate becomes -ic acid and -ite -ous acid.": "في الماء تصبح ‎-ate حمض ‎-ic و‎-ite حمض ‎-ous.",
    "Two nonmetals: a Greek prefix for how many atoms of each, mono- left off the first.": "لافلزان: بادئة يونانية لعدد ذرات كل منهما، دون mono- للأول.",
    "Known by a name of its own.": "معروف باسم خاص به.",
    "The cation, then the anion{v}": "الكاتيون ثم الأنيون{v}",
    "; a metal of more than one charge has its charge in Roman numerals, as the anions balance it.": "؛ والفلز متعدد الشحنات تُكتب شحنته بالأرقام الرومانية كما توازنها الأنيونات.",
    "Type a formula or an ion: K2Cr2O7, SO4^2-.": "اكتب صيغة أو أيونًا: K2Cr2O7، SO4^2-.",
    "An electron has no oxidation number: type a formula or an ion.": "لا عدد تأكسد للإلكترون: اكتب صيغة أو أيونًا.",
    "No oxidation numbers fit it, by the rules and the usual states of its elements.": "لا أعداد تأكسد تناسبها، وفق القواعد والحالات المعتادة لعناصرها.",
    "The rules leave more than one element: each is put in one of its usual states, so they add up to the charge.": "تترك القواعد أكثر من عنصر: فوُضع كل منها في إحدى حالاته المعتادة بحيث يساوي المجموع الشحنة.",
    "Each ion on its own, as {twice} is in both.": "كل أيون على حدة، لأن {twice} في كليهما.",
    "{v}: an average, as its atoms are not all in one state; Fe3O4 is FeO·Fe2O3.": "{v}: متوسط، لأن ذراته ليست كلها في حالة واحدة؛ ‏Fe3O4 هي FeO·Fe2O3.",
    "By the rules; the sum is the charge, {v}.": "وفق القواعد؛ والمجموع يساوي الشحنة، {v}.",
    "Density, g/L": "الكثافة، g/L",
