    "The same units of P and of V on both sides; T in °C, worked out in kelvin.": "الوحدات نفسها لـ P وV في الطرفين؛ وT بالدرجة المئوية، وتُحسب بالكلفن.",
    "The same units of P and of V on both sides; T in kelvin.": "الوحدات نفسها لـ P وV في الطرفين؛ وT بالكلفن.",
