    "By the standard atmosphere, ISA, from 15 °C and 1 atm at sea level; the weather moves it a few percent.": "وفق الغلاف الجوي القياسي ISA بدءًا من 15 °C و1 atm عند مستوى البحر؛ والطقس يغيّره ببضعة في المئة.",
