    "Golden spiral": "اللولب الذهبي",
    "Two arms growing by the golden ratio, (1 + √5)/2, each quarter turn. Turned by w it is the same spiral, only bigger: it seems to come at you.": "ذراعان تنموان بالنسبة الذهبية، (1 + √5)/2، كل ربع دورة. وإذا أدرته بـw كان اللولب نفسه، أكبر فقط: فيبدو كأنه يقترب منك.",
    "Heart curve": "منحنى القلب",
    "A heart, x and y each a sum of waves of t.": "قلب، x وy كلٌّ منهما مجموع موجات في t.",
    "Atom": "الذرة",
    "A nucleus, three orbits, each an ellipse turned 60° on from the one before, and an electron going round each as a plays: seven boxes.": "نواة وثلاثة مدارات، كل منها قطع ناقص مُدار 60° عن الذي قبله، وإلكترون يدور في كل منها مع تشغيل a: سبع خانات.",
    "Phases of the Moon": "أطوار القمر",
    "Lit where x is more than k√(9 – y²): new at k = 1, half at 0, full at –1.": "مضاء حيث x أكبر من k√(9 – y²): محاق عند k = 1، وتربيع عند 0، وبدر عند –1.",
    "Spirograph": "سبيروغراف",
    "A pen in a wheel rolling inside a ring, and in one rolling round it; d is how far the pen is from the middle of its wheel.": "قلم في عجلة تتدحرج داخل حلقة، وفي أخرى تتدحرج حولها؛ وd بُعد القلم عن مركز عجلته.",
    "A rod, the bob at its end and the arc it swings on, a its angle.": "قضيب، والثقل في طرفه والقوس الذي يتأرجح عليه، وa زاويته.",

